        #region SysBuildIndex_Activated
        private void SysBuildIndex_Activated(object sender, EventArgs e)
        {
            if (intExit > 0) return;
            //
            //chkReserialising.Checked = true;
            //chkRecalculation.Checked = true;
            //ckhReIndexing.Checked = true;
            //
            this.Cursor = Cursors.WaitCursor;
            //
