        #region bgwWorkerBuildIndex_ProgressChanged
        private void bgwWorkerBuildIndex_ProgressChanged(object sender, ProgressChangedEventArgs e)
        {
            //--
            if (e.ProgressPercentage >= 100)
            {
                lblPrcnt.Text = "100%";
                prgBar.Value = 100;
            }
            else
            {
                lblPrcnt.Text = e.ProgressPercentage.ToString() + "%";
                prgBar.Value = e.ProgressPercentage;
            }
            //--
            if (prgBar.Value > 25)
                chkReserialising.Checked = true;
            if (prgBar.Value > 55)
                chkRecalculation.Checked = true;
            if (prgBar.Value > 85)
                ckhReIndexing.Checked = true;
        }
        #endregion

        #region bgwWorkerBuildIndex_RunWorkerCompleted
        private void bgwWorkerBuildIndex_RunWorkerCompleted(object sender, RunWorkerCompletedEventArgs e)
        {
            if (e.Cancelled)
            {
                //MessageBox.Show("Update cancelled.");
                cmnService.J_UserMessage("Build Index cancelled.");
                //
                bgwWorkerBuildIndex.CancelAsync();
                bgwWorkerBuildIndex.Dispose();
                //
                this.Cursor = Cursors.Default;
                //
                BtnCancel.Text = "E&xit";
                prgBar.Value = 0;
                lblPrcnt.Text = "";
                return;
            }
            //--
            this.Cursor = Cursors.Default;
            //--
            if (prgBar.Value < 100)
            {
                prgBar.Value = 100;
                lblPrcnt.Text = "100%";
            }
            //--
            lblPleaseWaitMessage1.Visible = false;
            chkReserialising.Checked = true;
            //chkReserialising.BackColor = Color.Honeydew;
            chkRecalculation.Checked = true;
            //chkRecalculation.BackColor = Color.Honeydew;
            ckhReIndexing.Checked = true;
            //ckhReIndexing.BackColor = Color.Honeydew;
            //
            cmnService.J_UserMessage("Build Index Completed");
            //--
            bgwWorkerBuildIndex.CancelAsync();
            bgwWorkerBuildIndex.Dispose();
            //--
            this.Close();
            this.Dispose();
            //--
        }
        #endregion

